namespace ghidra.graph.algo.viewer;








using generic.theme;
using generic.theme.GThemeDefaults.Colors;
using ghidra.graph.algo.GraphAlgorithmStatusListener;
using ghidra.graph.graphs;
using ghidra.graph.viewer.vertex;

public class AlgorithmTestSteppingVertex<V> : AbstractTestVertex, VertexShapeProvider {

	private ShapeImage defaultShape;
	private ShapeImage defaultWithPathShape;
	private ShapeImage scheduledShape;
	private ShapeImage exploringShape;
	private ShapeImage blockedShape;
	private ShapeImage currentShape;

	private JLabel tempLabel = new JLabel();
	private V v;
	private STATUS status = STATUS.WAITING;

	private bool wasEverInPath;

	protected AlgorithmTestSteppingVertex(V v) : base(v.toString())
    {
		this.v = v;

		buildShapes();

		tempLabel.setText(v.toString());
	}

	public void setStatus(STATUS status) {
		this.status = status;

		ShapeImage si;
		switch (status) {
			case BLOCKED:
				si = blockedShape;
				if (wasEverInPath) {
					si = defaultWithPathShape;
				}
				break;
			case EXPLORING:
				si = exploringShape;
				break;
			case SCHEDULED:
				si = scheduledShape;
				break;
			case IN_PATH:
				si = exploringShape;
				wasEverInPath = true;
				break;
			case WAITING:
			default:
				si = defaultShape;
				if (wasEverInPath) {
					si = defaultWithPathShape;
				}
				break;
		}

		currentShape = si;
	}

	private void buildShapes() {

		defaultShape = buildCircleShape(Palette.LIGHT_GRAY, "default");
		defaultWithPathShape =
			buildCircleShape(new GColor("color.palette.yellowgreen"), "default; was in path");
		scheduledShape = buildCircleShape(new GColor("color.palette.khaki"), "scheduled");
		exploringShape = buildCircleShape(Palette.GREEN, "exploring");
		blockedShape = buildCircleShape(Palette.PINK, "blocked");

		currentShape = defaultShape;
	}

	private ShapeImage buildCircleShape(Color color, string name) {
		int w = 50;
		int h = 50;

		Double circle = new Ellipse2D.Double(0, 0, w, h);

		BufferedImage image = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g2 = (Graphics2D) image.getGraphics();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		g2.setColor(color);
		g2.fill(circle);

		g2.dispose();

		Dimension shapeSize = circle.getBounds().getSize();
		int x = 50;
		int y = 0;
		circle.setFrame(x, y, shapeSize.width, shapeSize.height);

		return new ShapeImage(image, circle, name);
	}

	V getTestVertex() {
		return v;
	}

	/* @Override */
	public JComponent getComponent() {
		ShapeImage si = getShapeImage();
		ImageIcon icon = new ImageIcon(si.getImage());
		tempLabel.setIcon(icon);
		return tempLabel;
	}

	private ShapeImage getShapeImage() {
		return currentShape;
	}

	/* @Override */
	public Shape getCompactShape() {
		return getShapeImage().getShape();
	}

	/* @Override */
	public string toString() {
		string statusString = status.toString();
		if (wasEverInPath) {
			statusString = "";
		}
		else if (status == STATUS.BLOCKED) {
			statusString = "";
		}

		return v.toString() + " " + statusString;
	}

	private class ShapeImage {
		private Image image;
		private Shape shape;
		private string shapeName;

		ShapeImage(Image image, Shape shape, string name) {
			this.image = image;
			this.shape = shape;
			this.shapeName = name;
		}

		Shape getShape() {
			return shape;
		}

		Image getImage() {
			return image;
		}

		string getName() {
			return shapeName;
		}

		/* @Override */
		public string toString() {
			return getName();
		}
	}
}
